 ("本地",[.init(title:"进入上级目录",identifier:"local.up",shortcut:""),.init(title:"进入根目录",identifier:"local.root",shortcut:""),.init(title:"编辑完整路径",identifier:"local.path",shortcut:""),.init(title:"刷新",identifier:"local.refresh",shortcut:""),.init(title:"目录书签",identifier:"local.bookmarks",shortcut:""),.init(title:"新建文件夹…",identifier:"local.mkdir",shortcut:"")]),
 ("远程",[.init(title:"进入上级目录",identifier:"remote.up",shortcut:""),.init(title:"进入根目录",identifier:"remote.root",shortcut:""),.init(title:"编辑完整路径",identifier:"remote.path",shortcut:""),.init(title:"刷新",identifier:"remote.refresh",shortcut:""),.init(title:"目录书签",identifier:"remote.bookmarks",shortcut:""),.init(title:"新建文件夹…",identifier:"remote.mkdir",shortcut:""),.init(title:"复制到远程目录…",identifier:"remoteCopy",shortcut:""),.init(title:"移动到远程目录…",identifier:"remoteMove",shortcut:""),.init(title:"新建符号链接…",identifier:"symlink",shortcut:""),.init(title:"打开 SSH 终端",identifier:"terminal",shortcut:"")]),
