 ("选项",[.init(title:"上传／下载／粘贴前确认选项",identifier:"confirmTransfer",shortcut:""),.init(title:"拖放前确认选项",identifier:"confirmDragTransfer",shortcut:""),.init(title:"筛选当前目录",identifier:"filterFocus",shortcut:""),.init(title:"按名称排序",identifier:"sortName",shortcut:"1"),.init(title:"按大小排序",identifier:"sortSize",shortcut:"2"),.init(title:"按修改时间排序",identifier:"sortDate",shortcut:"3"),.init(title:"按扩展名排序",identifier:"sortExtension",shortcut:"4"),.init(title:"按权限排序",identifier:"sortPermissions",shortcut:"5"),.init(title:"传输设置…",identifier:"settings",shortcut:""),.init(title:"显示 / 隐藏当前栏目录树",identifier:"tree",shortcut:""),.init(title:"切换当前栏隐藏文件",identifier:"hidden",shortcut:"")]),
 ("帮助",[.init(title:"操作说明",identifier:"help",shortcut:""),.init(title:"关于 MacSCP",identifier:"about",shortcut:"")])]
 static func build(target:AnyObject,action:Selector)->[NSMenuItem]{groups.map{title,commands in let item=NSMenuItem(title:title,action:nil,keyEquivalent:"");let menu=NSMenu(title:title);for command in commands{let child=NSMenuItem(title:command.title,action:action,keyEquivalent:command.shortcut);child.target=target;child.identifier = .init(command.identifier);if FileKeyAction.sortKeys[command.identifier] != nil{child.keyEquivalentModifierMask=[.command,.option]};CommanderAppearance.menu(child,key:command.identifier);menu.addItem(child)};item.submenu=menu;return item}}
